public TFMPages pages()
{
    TFMPages						ret = super();
    TFMPageLookup					lookupPage = new TFMPageLookup();
    TFMPageLookupConfiguration		lookupConfig;
    TFMPageOrderList				listPage = new TFMPageOrderList();

    TFMPageOrderListConfiguration	Listconfig;
    listPage.parmId('Pick4Pack');
    listPage.parmFilter(methodStr(MobDocPackingItems,Pick4PackOrderFilters));
    listPage.parmIcon('mainmenureportasfinished');
    listPage.parmTitle('@{PagePickOrderListTitle}');
    Listconfig = listPage.getConfiguration();
    Listconfig.parmNavigateTo('PickLines');
    Listconfig.parmId(MobConstants::Pick()); //Use Pick Service instead
    ret.addPage(listPage);

    lookupPage.parmId('PackingOrder');
    lookupPage.parmFilter(methodStr(MobDocPackingItems,PackingTablesFilter));
    lookupPage.parmIcon('mainmenureportasfinished');
    lookupPage.parmTitle('@{PackingOrder}');
    lookupPage.addAction('Pick4Pack',-5);
    lookupConfig = lookupPage.getConfiguration();
    lookupConfig.parmNavigateTo('Pick4Pack');
    lookupConfig.parmListId(classStr(TFMListLookupJournalHeader));
    lookupConfig.parmAutomaticAccept(TFMAutomaticAccept::OnOpen);
    lookupConfig.parmRefreshOnSuccess(true);
    ret.addPage(lookupPage);

    lookupPage = ret.getPage('FinishPackingOrder');

    lookupPage.parmFilter(methodStr(MobDocPackingItems,FinishPackingOrderFilter));
    lookupPage.parmIcon('postready');
    lookupPage.parmTitle('@{FinishPackingOrder}');
    lookupConfig = lookupPage.getConfiguration();
    lookupConfig.parmNavigateTo('FinishPackingOrderLines');
    lookupConfig.parmListId(classStr(TFMListLookupJournalHeader));
    lookupConfig.parmAutomaticAccept(TFMAutomaticAccept::OnOpen);
    lookupConfig.parmRefreshOnSuccess(true);
    ret.addPage(lookupPage);

    lookupPage = ret.getPage('FinishPackingOrderLines');
    lookupPage.parmFilter(methodStr(MobDocPackingItems,FinishPackingOrderLinesFilter));
    lookupPage.parmIcon('postready');
    lookupPage.parmTitle('@{StagingLines}');

    lookupPage.parmAvailableForMenuPages(false);
    lookupConfig = lookupPage.getConfiguration();
    lookupConfig.parmAutomaticAccept(TFMAutomaticAccept::OnOpen);

    lookupConfig.parmListId(classStr(TFMListLookupJournalHeader));
    lookupConfig.parmRefreshOnSuccess(true);
    lookupPage.addAction('FinishPackingOrderLinesContent',1,1);
    ret.addPage(lookupPage);

    lookupPage = new TFMPageLookup();
    lookupPage.parmId('FinishPackingOrderLinesContent');
    lookupPage.parmFilter(methodStr(MobDocPackingItems,FinishPackingOrderLinesContentFilter));
    lookupPage.parmIcon('postready');
    lookupPage.parmTitle('@{Repack}');
    lookupPage.parmAvailableForMenuPages(false);
    lookupConfig = lookupPage.getConfiguration();
    lookupConfig.parmUseRegistrationCollector('true');
    lookupConfig.parmListId(classStr(TFMListLookupNoSlash));
    lookupConfig.parmAutomaticAccept(TFMAutomaticAccept::OnOpen);
    lookupConfig.parmRefreshOnSuccess(true);        
    ret.addPage(lookupPage);

    return ret;
}

